CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', access_scope TEXT NOT NULL CHECK (access_scope IN ('user','admin')), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), is_system INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')), role_id INTEGER REFERENCES roles(id), status TEXT NOT NULL DEFAULT 'enabled' CHECK (status IN ('enabled','disabled')), is_superadmin INTEGER NOT NULL DEFAULT 0 CHECK (is_superadmin IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS features (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER REFERENCES features(id) ON DELETE RESTRICT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, route TEXT NOT NULL UNIQUE, icon TEXT NOT NULL DEFAULT 'layui-icon-app', category TEXT NOT NULL DEFAULT '自定义功能', description TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), sort_order INTEGER NOT NULL DEFAULT 100, is_system INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_features (role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, feature_id INTEGER NOT NULL REFERENCES features(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (role_id,feature_id));
CREATE TABLE IF NOT EXISTS menus (id INTEGER PRIMARY KEY AUTOINCREMENT, feature_id INTEGER NOT NULL UNIQUE REFERENCES features(id) ON DELETE CASCADE, title TEXT NOT NULL, icon TEXT NOT NULL DEFAULT 'layui-icon-app', category TEXT NOT NULL DEFAULT '自定义功能', sort_order INTEGER NOT NULL DEFAULT 100, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), is_system INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lookout_sources (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, base_url TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', default_headers TEXT NOT NULL DEFAULT '{}', enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS collection_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id INTEGER NOT NULL REFERENCES lookout_sources(id) ON DELETE CASCADE, name TEXT NOT NULL, keyword_param TEXT NOT NULL DEFAULT 'word', page_param TEXT NOT NULL DEFAULT 'pn', page_start INTEGER NOT NULL DEFAULT 0, page_step INTEGER NOT NULL DEFAULT 10 CHECK (page_step>0), page_size INTEGER NOT NULL DEFAULT 12 CHECK (page_size BETWEEN 1 AND 100), fixed_params TEXT NOT NULL DEFAULT '{}', request_headers TEXT NOT NULL DEFAULT '{}', parser_type TEXT NOT NULL DEFAULT 'generic_links', parser_config TEXT NOT NULL DEFAULT '{}', enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_id,name));
CREATE TABLE IF NOT EXISTS collection_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, rule_id INTEGER REFERENCES collection_rules(id) ON DELETE SET NULL, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, keyword TEXT NOT NULL, page_number INTEGER NOT NULL DEFAULT 1 CHECK (page_number>0), page_size INTEGER NOT NULL DEFAULT 12 CHECK (page_size BETWEEN 1 AND 100), request_url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','success','failed')), result_count INTEGER NOT NULL DEFAULT 0 CHECK (result_count>=0), error_message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TEXT);
CREATE TABLE IF NOT EXISTS collection_results (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES collection_runs(id) ON DELETE CASCADE, rule_id INTEGER REFERENCES collection_rules(id) ON DELETE SET NULL, title TEXT NOT NULL, url TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', source_name TEXT NOT NULL DEFAULT '', published_at TEXT NOT NULL DEFAULT '', raw_data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(run_id,url));
CREATE TABLE IF NOT EXISTS warehouse_items (id INTEGER PRIMARY KEY AUTOINCREMENT, source_result_id INTEGER REFERENCES collection_results(id) ON DELETE SET NULL, rule_id INTEGER REFERENCES collection_rules(id) ON DELETE SET NULL, title TEXT NOT NULL, url TEXT NOT NULL UNIQUE, summary TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', source_name TEXT NOT NULL DEFAULT '', published_at TEXT NOT NULL DEFAULT '', raw_data TEXT NOT NULL DEFAULT '{}', deep_collected INTEGER NOT NULL DEFAULT 0 CHECK (deep_collected IN (0,1)), created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_configs (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, model_name TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'OpenAI Compatible', model_type TEXT NOT NULL DEFAULT 'text' CHECK (model_type IN ('text','image','audio','video','multimodal','embedding')), base_url TEXT NOT NULL, api_key_env TEXT NOT NULL DEFAULT 'OPENAI_API_KEY', system_prompt TEXT NOT NULL DEFAULT '', temperature REAL NOT NULL DEFAULT 0.7 CHECK (temperature BETWEEN 0 AND 2), top_p REAL NOT NULL DEFAULT 1.0 CHECK (top_p BETWEEN 0 AND 1), max_tokens INTEGER NOT NULL DEFAULT 2048 CHECK (max_tokens BETWEEN 1 AND 131072), context_messages INTEGER NOT NULL DEFAULT 10 CHECK (context_messages BETWEEN 1 AND 100), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)), created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, model_id INTEGER NOT NULL REFERENCES model_configs(id) ON DELETE CASCADE, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, prompt_tokens INTEGER NOT NULL DEFAULT 0 CHECK (prompt_tokens>=0), completion_tokens INTEGER NOT NULL DEFAULT 0 CHECK (completion_tokens>=0), total_tokens INTEGER NOT NULL DEFAULT 0 CHECK (total_tokens>=0), latency_ms INTEGER NOT NULL DEFAULT 0 CHECK (latency_ms>=0), success INTEGER NOT NULL DEFAULT 1 CHECK (success IN (0,1)), error_message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS digital_employees (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, mention TEXT NOT NULL UNIQUE, employee_type TEXT NOT NULL CHECK (employee_type IN ('llm','api')), description TEXT NOT NULL DEFAULT '', model_id INTEGER REFERENCES model_configs(id) ON DELETE SET NULL, use_default_model INTEGER NOT NULL DEFAULT 1 CHECK (use_default_model IN (0,1)), system_prompt TEXT NOT NULL DEFAULT '', prompt_template TEXT NOT NULL DEFAULT '{{input}}', skills TEXT NOT NULL DEFAULT '[]', crawl4ai_enabled INTEGER NOT NULL DEFAULT 0 CHECK (crawl4ai_enabled IN (0,1)), crawl4ai_config TEXT NOT NULL DEFAULT '{}', api_method TEXT NOT NULL DEFAULT 'GET' CHECK (api_method IN ('GET','POST')), api_url TEXT NOT NULL DEFAULT '', request_headers TEXT NOT NULL DEFAULT '{}', request_params TEXT NOT NULL DEFAULT '{}', response_mode TEXT NOT NULL DEFAULT 'json' CHECK (response_mode IN ('json','card')), timeout_seconds INTEGER NOT NULL DEFAULT 20 CHECK (timeout_seconds BETWEEN 3 AND 60), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), is_system INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)), created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deep_collection_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, warehouse_item_id INTEGER NOT NULL REFERENCES warehouse_items(id) ON DELETE CASCADE, employee_id INTEGER REFERENCES digital_employees(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','success','failed')), progress INTEGER NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), current_step TEXT NOT NULL DEFAULT '等待调度', total_steps INTEGER NOT NULL DEFAULT 6 CHECK (total_steps>0), is_update INTEGER NOT NULL DEFAULT 0 CHECK (is_update IN (0,1)), started_by INTEGER REFERENCES users(id) ON DELETE SET NULL, error_message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS deep_collection_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES deep_collection_tasks(id) ON DELETE CASCADE, level TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info','success','warning','error')), step TEXT NOT NULL DEFAULT '', message TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deep_collection_results (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL UNIQUE REFERENCES deep_collection_tasks(id) ON DELETE CASCADE, warehouse_item_id INTEGER NOT NULL REFERENCES warehouse_items(id) ON DELETE CASCADE, employee_id INTEGER REFERENCES digital_employees(id) ON DELETE SET NULL, title TEXT NOT NULL, content TEXT NOT NULL, excerpt TEXT NOT NULL DEFAULT '', metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_conversations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT '新对话', model_id INTEGER REFERENCES model_configs(id) ON DELETE SET NULL, employee_id INTEGER REFERENCES digital_employees(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id INTEGER NOT NULL REFERENCES user_conversations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user','assistant')), content TEXT NOT NULL, content_type TEXT NOT NULL DEFAULT 'text' CHECK (content_type IN ('text','card','json','error')), metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
